SELECT C.NOME_CRITERIO AS CRITERIO, CASE WHEN C.TIPO_VALOR = 'Percentual' OR UPPER(C.NOME_CRITERIO) LIKE '%SEGURO%' THEN 'Percentual' ELSE 'Fixo' END AS TIPO_VALOR, ROUND(C.VALOR, 2) AS VALOR_UNITARIO, ROUND(CASE WHEN C.TIPO_VALOR = 'Percentual' OR UPPER(C.NOME_CRITERIO) LIKE '%SEGURO%' THEN GREATEST(0, P.SALDO_ATUAL_VALOR) ELSE GREATEST(0, P.PICO_PESO / 1000) END, 3) AS QUANTIDADE_BASE, ROUND(CASE WHEN C.TIPO_VALOR = 'Percentual' OR UPPER(C.NOME_CRITERIO) LIKE '%SEGURO%' THEN (GREATEST(0, P.SALDO_ATUAL_VALOR) * (C.VALOR / 100)) ELSE (GREATEST(0, P.PICO_PESO / 1000) * C.VALOR) END, 2) AS VALOR_TOTAL FROM VINCULO_PARCEIRO_TIPO V JOIN CRITERIO_COBRANCA C ON V.ID_TIPO_ARMAZENAGEM = C.ID_TIPO_ARMAZENAGEM CROSS JOIN (SELECT COALESCE((SELECT MAX(SALDO_PESO) FROM (SELECT DTNEG, SUM(CASE WHEN ATUALESTOQUE = 1 THEN PESO_ITEM WHEN ATUALESTOQUE = -1 THEN -PESO_ITEM ELSE 0 END) OVER (ORDER BY DTNEG, AUTO_ID) AS SALDO_PESO FROM IMP_NOTAS_ARMAZ WHERE CODPARC = :VAR_PARCEIRO_SELECIONADO AND DTNEG <= LAST_DAY(CONCAT(:VAR_MES_SELECIONADO, '-01'))) T1 WHERE DATE_FORMAT(DTNEG, '%Y-%m') = :VAR_MES_SELECIONADO), (SELECT IFNULL(SUM(CASE WHEN ATUALESTOQUE = 1 THEN PESO_ITEM WHEN ATUALESTOQUE = -1 THEN -PESO_ITEM ELSE 0 END), 0) FROM IMP_NOTAS_ARMAZ WHERE CODPARC = :VAR_PARCEIRO_SELECIONADO AND DTNEG < CONCAT(:VAR_MES_SELECIONADO, '-01'))) AS PICO_PESO, (SELECT IFNULL(SUM(VALOR_TOTAL), 0) FROM (SELECT SUM(CASE WHEN ATUALESTOQUE = 1 THEN (VLRUNIT * QTDNEG) WHEN ATUALESTOQUE = -1 THEN -(VLRUNIT * QTDNEG) ELSE 0 END) AS VALOR_TOTAL FROM IMP_NOTAS_ARMAZ WHERE CODPARC = :VAR_PARCEIRO_SELECIONADO GROUP BY DESCRPROD HAVING SUM(CASE WHEN DATE_FORMAT(DTNEG, '%Y-%m') = :VAR_MES_SELECIONADO THEN 1 ELSE 0 END) > 0 OR ROUND(SUM(CASE WHEN ATUALESTOQUE = 1 THEN PESO_ITEM WHEN ATUALESTOQUE = -1 THEN -PESO_ITEM ELSE 0 END), 2) <> 0) T_SALDO) AS SALDO_ATUAL_VALOR FROM DUAL) P WHERE V.CODPARC = :VAR_PARCEIRO_SELECIONADO ORDER BY C.NOME_CRITERIO